describe('Instance AI quota errors', () => {
	it('surfaces the top-level code as errorCode and preserves the message on a quota 403', async () => {
		nock(BASE_URL).post('/v1/instance-ai/api-proxy-token').once().reply(403, {
			statusCode: 403,
			error: 'Forbidden',
			message: 'Have reached end of quota',
			code: 'quota_exhausted',
		});

		const error = await client
			.getInstanceAiApiProxyToken({ id: USER_ID })
			.then(() => undefined)
			.catch((e: unknown) => e);

		assert.ok(error instanceof APIResponseError);
		assert.strictEqual(error.errorCode, 'quota_exhausted');
		assert.strictEqual(error.statusCode, 403);
		assert.strictEqual(error.message, 'Have reached end of quota');
	});

	it('falls back to a nested error.type for the code', async () => {
		nock(BASE_URL)
			.post('/v1/instance-ai/api-proxy-token')
			.once()
			.reply(403, {
				error: { type: 'quota_exhausted', message: 'Have reached end of quota' },
			});

		const error = await client
			.getInstanceAiApiProxyToken({ id: USER_ID })
			.then(() => undefined)
			.catch((e: unknown) => e);

		assert.ok(error instanceof APIResponseError);
		assert.strictEqual(error.errorCode, 'quota_exhausted');
		assert.strictEqual(error.message, 'Have reached end of quota');
	});

	it('leaves errorCode undefined for an error body without a code', async () => {
		nock(BASE_URL)
			.post('/v1/instance-ai/api-proxy-token')
			.once()
			.reply(403, { statusCode: 403, error: 'Forbidden', message: 'Forbidden' });

		const error = await client
			.getInstanceAiApiProxyToken({ id: USER_ID })
			.then(() => undefined)
			.catch((e: unknown) => e);

		assert.ok(error instanceof APIResponseError);
		assert.strictEqual(error.errorCode, undefined);
		assert.strictEqual(error.message, 'Forbidden');
	});
});

describe('APIResponseError', () => {
	it('should use level "warning" for 4xx client errors', () => {
		for (const statusCode of [400, 401, 403, 404, 429, 499]) {
			const error = new APIResponseError('client error', statusCode);
			assert.strictEqual(error.level, 'warning', `expected warning for ${statusCode}`);
			assert.strictEqual(error.statusCode, statusCode);
		}
	});

	it('should use level "error" for 5xx server errors', () => {
		for (const statusCode of [500, 502, 503, 504]) {
			const error = new APIResponseError('server error', statusCode);
			assert.strictEqual(error.level, 'error', `expected error for ${statusCode}`);
		}
	});

	it('should use level "error" when no status code is provided', () => {
		const error = new APIResponseError('no status code');
		assert.strictEqual(error.level, 'error');
		assert.strictEqual(error.statusCode, undefined);
	});
});
